    : type === 'trend-down' ? candleRows.down
    : type === 'range' || type === 'premium' || type === 'time' || type === 'three-drives' || type === 'po3' || type === 'turtle' || type === 'weekly' || type === 'platform' || type === 'orders' || type === 'risk' || type === 'calendar' || type === 'opening-gap' || type === 'stats' ? candleRows.range
    : type === 'choch' ? candleRows.choch
    : type === 'swing' ? candleRows.swing
    : type === 'sweep' || type === 'liquidity' || type === 'inducement' || type === 'smt' || type === 'vacuum' || type === 'internal-external' ? candleRows.sweep
    : type === 'fvg' || type === 'bpr' || type === 'imbalance' ? candleRows.fvg
    : type === 'ifvg' ? candleRows.ifvg
    : type === 'ob' || type === 'mitigation' || type === 'rejection' ? candleRows.ob
    : type === 'breaker' ? candleRows.breaker
    : type === 'mss' || type === 'cisd' || type === 'displacement' ? candleRows.up
    : candleRows.range
  return rows.map(([x,open,close,wickTop,wickBottom]) => ({x,open,close,wickTop,wickBottom,up:close<open}))
}
