const lessonContent = id => {
  const content = {
    1: { heading: 'Entendé qué estás haciendo cuando operás', intro: 'El trading consiste en tomar decisiones bajo incertidumbre sobre el movimiento del precio. El libro propone aprender primero el funcionamiento del mercado y después estudiar modelos técnicos; ninguna metodología elimina el riesgo.', points: [{ title: 'Hipótesis', text: 'Toda operación parte de una idea sobre lo que podría hacer el precio.' }, { title: 'Plan', text: 'Definí condición de entrada, invalidación y objetivo antes de ejecutar.' }, { title: 'Riesgo', text: 'Una buena lectura puede fallar; protegé el capital y registrá los resultados.' }], traderNote: 'No necesitás acertar siempre. Necesitás un proceso repetible, riesgo controlado y suficiente práctica para evaluar si tu método funciona.', mistake: 'Confundir una operación ganadora con una buena decisión o una perdedora con una mala decisión sin revisar el plan.', question: '¿Qué debe existir antes de ejecutar una operación?', options: ['Una hipótesis, un plan y un riesgo definido', 'La certeza de que el precio va a subir', 'Una vela grande sin contexto'], correct: 0, feedback: 'Correcto: el mercado es incierto; un plan y la gestión del riesgo son esenciales.' },
    5: { heading: 'La estructura es el mapa de máximos y mínimos', intro: 'El libro presenta tres estados principales: tendencia alcista, tendencia bajista y consolidación. Los swing points ayudan a decidir qué máximos y mínimos importan.', points: [{ title: 'HH + HL', text: 'Secuencia de máximos más altos y mínimos más altos: estructura alcista.' }, { title: 'LH + LL', text: 'Secuencia de máximos más bajos y mínimos más bajos: estructura bajista.' }, { title: 'Rango', text: 'Los extremos no progresan de forma consistente; no fuerces una tendencia.' }], traderNote: 'Primero marcá los swings importantes. Después preguntate qué nivel tendría que romperse para cambiar tu lectura.', mistake: 'Confundir un retroceso con un cambio confirmado de tendencia.', question: 'El precio repite máximos y mínimos dentro del mismo rango. ¿Qué estado describe mejor?', options: ['Tendencia alcista', 'Tendencia bajista', 'Consolidación'], correct: 2, feedback: 'Exacto: cuando no hay progresión clara de máximos y mínimos, lo más prudente es reconocer un rango.' },
    6: { heading: 'Los swings son los pivotes del precio', intro: 'Un Swing High es un máximo local donde el precio deja de subir y gira. Un Swing Low es un mínimo local donde deja de caer y rebota. Son referencias para estructura y liquidez.', points: [{ title: 'Swing High', text: 'En el esquema básico del libro, la vela central tiene un máximo superior a las velas adyacentes.' }, { title: 'Swing Low', text: 'La vela central tiene un mínimo inferior a las velas adyacentes.' }, { title: 'Importancia', text: 'No todos los swings tienen la misma relevancia: priorizá los que definen la estructura.' }], traderNote: 'No marques cada pequeño zigzag. Preguntate si el swing cambió el flujo o si es ruido dentro del movimiento.', mistake: 'Usar cualquier máximo local como si fuera un nivel estructural mayor.', question: '¿Para qué sirve principalmente un swing relevante?', options: ['Para definir referencias de estructura y liquidez', 'Para garantizar el próximo movimiento', 'Para reemplazar la gestión del riesgo'], correct: 0, feedback: 'Bien: los swings son referencias para estructura, rupturas y posibles objetivos de liquidez, no garantías.' },
    8: { heading: 'El displacement muestra decisión', intro: 'Displacement es un movimiento direccional claro, con velas amplias y poco solapamiento relativo. En el enfoque del libro, ayuda a valorar si una ruptura tiene fuerza.', points: [{ title: 'Cuerpo amplio', text: 'El precio avanza con decisión, no solo con una mecha aislada.' }, { title: 'Ruptura', text: 'Puede quebrar un swing relevante y mostrar cambio en el flujo.' }, { title: 'Desequilibrio', text: 'A menudo deja una FVG que luego puede actuar como zona de interés.' }], traderNote: 'Una ruptura de nivel con cierre y desplazamiento es más informativa que un pinchazo de mecha que vuelve al rango.', mistake: 'Llamar displacement a cualquier vela grande sin revisar el contexto ni el nivel que rompió.', question: '¿Qué acompaña mejor a un displacement relevante?', options: ['Una vela pequeña dentro del rango', 'Movimiento decisivo que rompe un nivel significativo', 'Solo un cruce de medias móviles'], correct: 1, feedback: 'Correcto: importan la fuerza del movimiento y el nivel estructural que rompe.' },
    9: { heading: 'BOS: ruptura a favor de la tendencia', intro: 'El Break of Structure se utiliza para describir una ruptura de estructura en la dirección de la tendencia vigente. El nivel debe ser relevante para la lectura del mercado.', points: [{ title: 'BOS alcista', text: 'En una estructura alcista, el precio rompe un máximo relevante y refuerza la continuidad.' }, { title: 'BOS bajista', text: 'En una estructura bajista, el precio rompe un mínimo relevante y refuerza la continuidad.' }, { title: 'Calidad de ruptura', text: 'Evaluá cierre, desplazamiento y contexto; no toda mecha es una ruptura válida.' }], traderNote: 'BOS no significa siempre bajista ni siempre alcista: depende de la dirección de la estructura que continúa.', mistake: 'Clasificar BOS por el color de la vela o porque rompió cualquier máximo/mínimo menor.', question: 'En tendencia bajista, el precio rompe un LL relevante y continúa cayendo. ¿Qué sugiere?', options: ['BOS bajista', 'CHOCH alcista', 'IFVG alcista automáticamente'], correct: 0, feedback: 'Sí: la ruptura acompaña la dirección bajista previa, por eso se clasifica como BOS bajista.' },
    10: { heading: 'CHOCH: una ruptura contra el flujo previo', intro: 'El Change of Character marca una ruptura estructural en sentido contrario a la tendencia anterior y advierte de una posible reversión. No garantiza que ya haya nacido una tendencia nueva.', points: [{ title: 'Posible CHOCH alcista', text: 'En tendencia bajista, el precio rompe un LH relevante hacia arriba.' }, { title: 'Posible CHOCH bajista', text: 'En tendencia alcista, el precio rompe un HL relevante hacia abajo.' }, { title: 'Confirmación posterior', text: 'Observá el retroceso y la estructura que se forme después; el contexto sigue mandando.' }], traderNote: 'Preguntate siempre: ¿qué tendencia había antes y qué swing estructural rompió el precio en contra de ella?', mistake: 'Pensar que CHOCH es siempre alcista o que una ruptura garantiza la reversión.', question: 'El mercado viene bajista y rompe hacia arriba el último LH estructural. ¿Qué podría ser?', options: ['BOS bajista', 'CHOCH alcista', 'BOS alcista confirmado sin más contexto'], correct: 1, feedback: 'Correcto: romper un LH en contra de una tendencia bajista puede señalar CHOCH alcista, es decir, una posible reversión.' },
    11: { heading: 'MSS: cambio estructural con desplazamiento', intro: 'El libro presenta el Market Structure Shift como una señal inicial de reversión, especialmente cuando la ruptura de un swing relevante se acompaña de displacement.', points: [{ title: 'Swing relevante', text: 'Identificá el máximo o mínimo que define el flujo previo.' }, { title: 'Ruptura con cuerpo', text: 'Una vela que cierra más allá del nivel y se mueve con decisión aporta evidencia.' }, { title: 'Confluencia', text: 'El MSS gana contexto si aparece cerca de un POI como OB o FVG.' }], traderNote: 'El MSS y el CHOCH se usan de manera algo distinta según el enfoque; en este libro, el desplazamiento es un rasgo importante del MSS.', mistake: 'Usar MSS, CHOCH y BOS como sinónimos sin mirar si la ruptura va a favor o en contra del flujo previo.', question: '¿Qué rasgo enfatiza el libro para evaluar un MSS?', options: ['Ruptura de swing en contra de tendencia con desplazamiento', 'Solo una mecha que atraviesa el nivel', 'El cruce de dos medias móviles'], correct: 0, feedback: 'Exacto: el libro destaca la ruptura de swing contraria a la tendencia y un desplazamiento claro.' },
    15: { heading: 'Un Order Block es una zona, no una entrada automática', intro: 'El OB se identifica como una zona asociada al origen de un movimiento relevante. Su utilidad aumenta cuando se integra con estructura, liquidez y desplazamiento.', points: [{ title: 'Origen', text: 'Buscá la vela o pequeña zona previa al impulso que genera un movimiento significativo.' }, { title: 'Contexto', text: 'Revisá qué estructura rompió el impulso y si dejó una FVG.' }, { title: 'Validación', text: 'Una zona puede fallar; definí invalidación y esperá reacción, no anticipes por tocarla.' }], traderNote: 'No marques cada vela contraria al movimiento. Pedí una razón estructural para considerar que el bloque importa.', mistake: 'Entrar automáticamente al primer toque de cualquier OB sin confirmación ni gestión del riesgo.', question: '¿Qué mejora la calidad de un OB como punto de interés?', options: ['Que sea cualquier vela roja/verde', 'Que esté asociado a desplazamiento y contexto estructural', 'Que nunca haya sido testeado'], correct: 1, feedback: 'Bien: el OB necesita contexto y evidencia; no toda vela previa a un impulso es una zona útil.' },
    17: { heading: 'Breaker Block: el bloque fallido cambia de función', intro: 'El glosario del libro define el Breaker Block como un Order Block roto que invierte su función: una zona de soporte puede actuar como resistencia, o viceversa.', points: [{ title: 'Bloque original', text: 'Identificá primero el OB y la función que tenía en el contexto anterior.' }, { title: 'Fallo y ruptura', text: 'El precio atraviesa el bloque de forma relevante, invalidando su función previa.' }, { title: 'Retesteo', text: 'La zona solo demuestra el cambio de rol si al regresar actúa desde el lado opuesto.' }], traderNote: 'Si un OB alcista se rompe hacia abajo y luego actúa como resistencia, puede convertirse en breaker bajista. No alcanza con que otra vela lo toque.', mistake: 'Llamar Breaker a cualquier OB roto sin verificar el cambio de función y la reacción posterior.', question: '¿Qué define mejor un Breaker Block?', options: ['Cualquier FVG sin rellenar', 'Un OB fallido que invierte su función', 'Un máximo igual a otro máximo'], correct: 1, feedback: 'Exacto: la clave del Breaker es el OB fallido y la inversión de su función.' },
    22: { heading: 'FVG: una ineficiencia entre tres velas', intro: 'El libro define la Fair Value Gap como un desequilibrio representado por el espacio entre los rangos de la primera y la tercera vela de una secuencia de tres.', points: [{ title: 'Tres velas', text: 'La vela central genera el movimiento; compará los extremos de la primera y la tercera.' }, { title: 'Desequilibrio', text: 'La zona refleja un movimiento rápido con poca negociación relativa entre esos extremos.' }, { title: 'Retorno posible', text: 'El precio puede regresar a la zona, pero no existe obligación de rellenarla ni garantía de reacción.' }], traderNote: 'Marcá primero los extremos exactos. Después observá si el precio la rellena, la respeta o la atraviesa.', mistake: 'Dibujar FVG solo porque una vela fue grande o asumir que el precio siempre volverá a llenarla.', question: '¿Qué necesitás para identificar una FVG clásica?', options: ['Una secuencia de tres velas con desequilibrio entre la primera y la tercera', 'Dos medias móviles cruzadas', 'Un RSI por encima de 70'], correct: 0, feedback: 'Correcto: la FVG se identifica comparando los extremos de una secuencia de tres velas.' },
    23: { heading: 'IFVG: cuando una FVG cambia de papel', intro: 'Una Inverse Fair Value Gap aparece cuando una FVG previa es rellenada y atravesada, invalidando su función original y haciendo que pueda actuar como soporte o resistencia en sentido opuesto.', points: [{ title: 'FVG original', text: 'Identificá primero si era una brecha alcista o bajista.' }, { title: 'Cruce completo', text: 'El precio debe atravesar la zona; un simple toque no basta para llamarla inversa.' }, { title: 'Nueva función', text: 'Observá si el precio vuelve y la zona actúa desde el lado contrario.' }], traderNote: 'Una FVG bajista atravesada al alza puede convertirse en IFVG alcista si pasa a actuar como soporte; la dirección inversa aplica igual.', mistake: 'Llamar IFVG a cualquier FVG que el precio toca, sin comprobar que la haya atravesado y cambiado de función.', question: '¿Qué condición es esencial para hablar de IFVG?', options: ['Que la zona se toque una vez', 'Que la FVG se atraviese y cambie de función', 'Que el precio esté por encima de una EMA'], correct: 1, feedback: 'Exacto: la inversión de función después de atravesar la zona es la característica central de una IFVG.' },
    28: { heading: 'La liquidez ayuda a entender los objetivos del precio', intro: 'En SMC, la liquidez suele estudiarse alrededor de máximos y mínimos evidentes donde pueden acumularse órdenes, incluidos stops. El precio puede dirigirse a esas áreas antes de continuar o revertir.', points: [{ title: 'BSL', text: 'Buy-Side Liquidity: liquidez por encima de máximos relevantes.' }, { title: 'SSL', text: 'Sell-Side Liquidity: liquidez por debajo de mínimos relevantes.' }, { title: 'Sweep', text: 'El precio atraviesa un nivel y puede regresar rápidamente; no es lo mismo que una ruptura sostenida.' }], traderNote: 'No supongas que todo barrido va a revertir. Mirá qué hace el precio después y si aparece displacement o un cambio estructural.', mistake: 'Confundir una mecha que barre liquidez con una ruptura confirmada o anticipar la reversión sin evidencia.', question: '¿Dónde suele ubicarse la BSL?', options: ['Debajo de mínimos relevantes', 'Encima de máximos relevantes', 'Siempre en el punto medio de una FVG'], correct: 1, feedback: 'Correcto: la BSL suele localizarse por encima de máximos significativos, donde pueden acumularse buy stops.' },
    33: { heading: 'Un Liquidity Sweep barre un nivel; la reacción importa', intro: 'El libro describe el barrido de liquidez como un movimiento que activa órdenes stop por encima o debajo de un nivel clave y puede revertir con rapidez.', points: [{ title: 'Nivel visible', text: 'Ubicá máximos o mínimos donde probablemente se concentren órdenes.' }, { title: 'Barrido', text: 'El precio cruza el nivel y puede volver al rango.' }, { title: 'Reacción', text: 'Buscá displacement, FVG o cambio estructural para evaluar si hay una reversión potencial.' }], traderNote: 'El sweep es el evento de captura de liquidez; la señal operativa, si existe, aparece en cómo reacciona el precio después.', mistake: 'Entrar en contra apenas una mecha rompe un máximo o mínimo.', question: '¿Qué conviene observar después de un posible sweep?', options: ['La reacción y el desplazamiento posteriores', 'Ignorar el cierre de la vela', 'Dar por garantizada la reversión'], correct: 0, feedback: 'Sí: el barrido por sí solo no confirma reversión; el comportamiento posterior ayuda a evaluar el escenario.' },
    34: { heading: 'El punto medio ayuda a precisar una zona', intro: 'El Consequent Encroachment (CE) se refiere al 50 % de un desequilibrio como una FVG; Mean Threshold (MT) se usa para el punto medio de un Order Block u otra estructura.', points: [{ title: 'CE en FVG', text: 'Calculá el punto medio entre los límites de la brecha.' }, { title: 'MT en OB', text: 'El 50 % del bloque puede servir como referencia de reacción.' }, { title: 'No es garantía', text: 'Son niveles de interés, no señales autónomas de entrada.' }], traderNote: 'Usá el punto medio para precisar una zona, pero combiná la lectura con contexto y confirmación.', mistake: 'Tratar el 50 % como si tuviera que provocar siempre un rebote.', question: '¿Qué representa el CE dentro de una FVG?', options: ['El punto medio del desequilibrio', 'El último máximo semanal', 'El stop loss obligatorio'], correct: 0, feedback: 'Correcto: CE es el punto medio de un desequilibrio como una FVG.' },
    43: { heading: 'Daily Bias: un escenario, no una predicción infalible', intro: 'El sesgo diario intenta organizar la dirección probable del día usando estructura, desequilibrios y el próximo objetivo de liquidez. No se trata de adivinar con certeza.', points: [{ title: 'Flujo diario', text: 'Evaluá si el gráfico mayor muestra HH/HL o LH/LL.' }, { title: 'Objetivo de liquidez', text: 'Ubicá posibles máximos o mínimos que el precio podría buscar.' }, { title: 'Eventos y tiempo', text: 'Considerá sesiones y calendario económico; pueden cambiar volatilidad y escenario.' }], traderNote: 'Definí qué tendría que pasar para invalidar tu sesgo. Si el precio contradice la hipótesis, actualizá el análisis.', mistake: 'Convertir el sesgo en una opinión rígida y descartar toda evidencia contraria.', question: '¿Qué describe mejor el Daily Bias?', options: ['Una certeza sobre el cierre del día', 'Un escenario direccional probable basado en contexto', 'Una orden automática de entrada'], correct: 1, feedback: 'Exacto: es una hipótesis direccional contextual, no una garantía.' },
    2: { heading: 'Las velas cuentan una historia de precio', intro: 'Una vela resume la apertura, el máximo, el mínimo y el cierre de un intervalo. El SMC se apoya en esos datos para leer desplazamiento, rechazo y estructura.', points: [{ title: 'Cuerpo', text: 'La distancia entre apertura y cierre; muestra dónde terminó el intervalo respecto de donde empezó.' }, { title: 'Mechas', text: 'Muestran extremos visitados por el precio, pero no sostenidos al cierre.' }, { title: 'Contexto', text: 'Una vela aislada no define tendencia ni estructura: comparala con swings y niveles previos.' }], traderNote: 'La mecha puede mostrar rechazo; el cierre ayuda a evaluar si el precio sostuvo la ruptura.', mistake: 'Interpretar el color de una vela como señal suficiente de compra o venta.', question: '¿Qué representa el cuerpo de una vela?', options: ['La distancia entre apertura y cierre', 'El volumen negociado exacto de cada precio', 'La tendencia completa del mercado'], correct: 0, feedback: 'Correcto: el cuerpo muestra la distancia entre apertura y cierre.' },
    3: { heading: 'Las órdenes forman parte del plan, no del análisis estructural', intro: 'Las órdenes de mercado, límite y stop tienen formas distintas de entrar o salir. La plataforma ejecuta la orden; no valida que la idea SMC sea correcta.', points: [{ title: 'Orden de mercado', text: 'Busca ejecutar al mejor precio disponible; el precio final puede variar.' }, { title: 'Orden límite', text: 'Define un precio máximo de compra o mínimo de venta, pero puede no ejecutarse.' }, { title: 'Stop y riesgo', text: 'Los stops ayudan a controlar el riesgo, aunque pueden ejecutarse con deslizamiento en condiciones rápidas.' }], traderNote: 'Primero definí la hipótesis y la invalidación; después elegí la orden apropiada para tu plan.', mistake: 'Confundir saber colocar una orden con tener una ventaja estadística.', question: '¿Una orden límite garantiza que la operación se ejecute?', options: ['Sí, siempre', 'No; el mercado puede no tocar el precio', 'Solo cuando hay una FVG'], correct: 1, feedback: 'Bien: una orden límite puede quedar sin ejecutar si el mercado no alcanza su precio.' },
    4: { heading: 'Prepará un entorno repetible de estudio', intro: 'La plataforma es una herramienta para observar y registrar el mercado. Una plantilla clara, capturas consistentes y backtesting ayudan a comprobar si interpretás los conceptos de forma repetible.', points: [{ title: 'Gráfico limpio', text: 'Mostrá solo herramientas que tengan una función concreta dentro de tu método.' }, { title: 'Registro', text: 'Guardá la hipótesis, el nivel, la confirmación y el resultado para revisar errores.' }, { title: 'Práctica', text: 'Probá primero en replay o paper trading antes de arriesgar dinero real.' }], traderNote: 'La consistencia del proceso vale más que llenar el gráfico de indicadores.', mistake: 'Cambiar reglas después de cada operación y no llevar registro.', question: '¿Qué ayuda más a evaluar un método SMC?', options: ['Cambiar las reglas en cada operación', 'Registrar y revisar una muestra de operaciones', 'Usar la mayor cantidad posible de indicadores'], correct: 1, feedback: 'Correcto: el registro y la revisión de una muestra permiten detectar patrones y errores.' },
    7: { heading: 'Strong y Weak Points: fuerza relativa de los swings', intro: 'El libro usa puntos fuertes y débiles para evaluar qué extremos pueden sostenerse y cuáles podrían ser vulnerables a una toma de liquidez. No es una propiedad garantizada: se interpreta en contexto.', points: [{ title: 'Punto débil', text: 'Un extremo que el contexto sugiere vulnerable a ser alcanzado o barrido.' }, { title: 'Punto fuerte', text: 'Un extremo que por estructura y reacción parece más defendido.' }, { title: 'Contexto', text: 'La clasificación depende del flujo, la liquidez y los swings que rodean al nivel.' }], traderNote: 'Usá estos términos como hipótesis de estructura, no como certeza sobre dónde se dará vuelta el mercado.', mistake: 'Asumir que un punto etiquetado fuerte jamás será roto.', question: '¿Cómo conviene tratar un Strong o Weak Point?', options: ['Como una hipótesis contextual', 'Como garantía de soporte o resistencia', 'Como sustituto de BOS y CHOCH'], correct: 0, feedback: 'Exacto: la etiqueta orienta el análisis, pero el precio puede invalidarla.' },
    12: { heading: 'CISD: cambio en el estado de entrega del precio', intro: 'El Change in the State of Delivery describe un cambio en la dirección en que se está entregando el precio: de flujo comprador a vendedor o viceversa. Se interpreta observando el comportamiento de las velas y su relación con niveles relevantes.', points: [{ title: 'Flujo anterior', text: 'Identificá qué lado venía impulsando el precio y qué niveles sostenían ese movimiento.' }, { title: 'Cambio observable', text: 'Buscá señales de que la entrega del precio deja de favorecer al flujo anterior.' }, { title: 'Contexto estructural', text: 'Relacioná el CISD con swings, liquidez y zonas de interés; no lo aísles de la estructura.' }], traderNote: 'El CISD es una forma de describir un cambio en el comportamiento del precio; exigí evidencia y definí qué invalidaría tu lectura.', mistake: 'Usar CISD como sinónimo de cualquier vela de color contrario.', question: '¿Qué describe el CISD?', options: ['Un cambio en la dirección de entrega del precio', 'Un objetivo fijo de ganancias', 'Una FVG por definición'], correct: 0, feedback: 'Exacto: CISD se refiere a un cambio del flujo de entrega del precio y debe leerse en contexto.' },
    13: { heading: 'Oferta y demanda son zonas, no líneas mágicas', intro: 'El libro presenta la oferta como región donde puede aparecer presión vendedora y la demanda como región donde puede aparecer presión compradora. Los movimientos agresivos que salen de una zona aportan contexto.', points: [{ title: 'Demanda', text: 'Área desde la que el precio rebotó con fuerza, potencialmente por predominio comprador.' }, { title: 'Oferta', text: 'Área desde la que el precio cayó con fuerza, potencialmente por predominio vendedor.' }, { title: 'Validación', text: 'Cuanto más claro el impulso y más relevante la estructura, más útil es estudiar la zona.' }], traderNote: 'No alcanza con dibujar un rectángulo. Preguntate qué movimiento salió de allí y qué nivel estructural cambió.', mistake: 'Comprar cada visita a demanda o vender cada visita a oferta sin esperar reacción.', question: '¿Qué evidencia hace más interesante una zona de oferta o demanda?', options: ['Un movimiento fuerte y claro que parte de ella', 'Que esté dibujada en cualquier lugar', 'Que el precio no se haya movido nunca'], correct: 0, feedback: 'Correcto: un movimiento claro y el contexto posterior ayudan a justificar la zona.' },
    14: { heading: 'Premium y Discount ubican el precio dentro de un rango', intro: 'El enfoque divide un rango relevante en mitades. En términos generales, la mitad superior se considera premium y la inferior discount; la lectura depende de qué rango se haya elegido.', points: [{ title: 'Definí el rango', text: 'Usá extremos estructurales relevantes, no puntos elegidos para justificar una entrada.' }, { title: 'Premium', text: 'Mitad superior del rango; se estudia con interés en escenarios de venta cuando el sesgo es bajista.' }, { title: 'Discount', text: 'Mitad inferior; puede ser zona de interés comprador cuando el sesgo es alcista.' }], traderNote: 'Premium/discount no indica por sí solo comprar o vender. Primero establecé dirección y objetivo de liquidez.', mistake: 'Tomar cualquier precio en discount como compra automática.', question: '¿Qué necesitás antes de marcar premium y discount?', options: ['Un rango relevante con extremos definidos', 'Solo una vela verde', 'Un cruce de medias'], correct: 0, feedback: 'Bien: sin un rango coherente, la división en premium y discount carece de contexto.' },
    16: { heading: 'Mitigation Block: una zona vinculada a mitigación', intro: 'El Mitigation Block es una de las variantes de bloques estudiadas en el libro. Se interpreta como una zona donde el precio vuelve a negociar posiciones previas dentro de un contexto estructural.', points: [{ title: 'Leé la estructura', text: 'Identificá la tendencia y el swing que importa antes de marcar el bloque.' }, { title: 'Buscá la reacción', text: 'La zona necesita una respuesta observable del precio, no solo un rectángulo.' }, { title: 'Compará con otros bloques', text: 'No confundas Mitigation Block con OB o Breaker: la lógica específica importa.' }], traderNote: 'Si no podés explicar qué evento estructural justifica la zona, todavía no tenés un marcado sólido.', mistake: 'Usar nombres distintos para el mismo bloque sin criterios definidos.', question: '¿Qué conviene hacer al estudiar un Mitigation Block?', options: ['Identificar su contexto y criterios específicos', 'Tratarlo siempre como un FVG', 'Ignorar la estructura'], correct: 0, feedback: 'Correcto: cada tipo de bloque tiene condiciones y debe leerse dentro de la estructura.' },
    18: { heading: 'Vacuum Block: observá el desplazamiento y el vacío', intro: 'El Vacuum Block se estudia dentro de las variantes de bloques. Su lectura se relaciona con un movimiento que atraviesa una zona con poca oposición; el contexto del impulso es esencial.', points: [{ title: 'Movimiento rápido', text: 'Observá si el precio avanzó de manera marcada por un área.' }, { title: 'Zona de referencia', text: 'Identificá qué parte del movimiento se está considerando como bloque.' }, { title: 'Confirmación', text: 'No asumas que la zona va a actuar como soporte o resistencia sin observar el retorno.' }], traderNote: 'El nombre no reemplaza la evidencia: mirá cómo se comporta el precio cuando vuelve a la zona.', mistake: 'Convertir una zona de movimiento rápido en entrada automática.', question: '¿Qué deberías comprobar si el precio regresa a un Vacuum Block?', options: ['Su reacción real en la zona', 'Que la operación tenga ganancia garantizada', 'Solo el color de la última vela'], correct: 0, feedback: 'Exacto: la reacción al regreso aporta información; la zona no garantiza un resultado.' },
    19: { heading: 'Propulsion Block: continuidad y contexto', intro: 'El Propulsion Block es otra variante de bloque del libro, utilizada para estudiar zonas relacionadas con la continuación del movimiento. Su lectura debe apoyarse en la dirección del flujo.', points: [{ title: 'Flujo previo', text: 'Definí si el mercado está en contexto alcista o bajista.' }, { title: 'Impulso', text: 'Observá cómo la zona participa en la continuación del movimiento.' }, { title: 'Retesteo', text: 'Si el precio vuelve, analizá si respeta la zona o la atraviesa.' }], traderNote: 'La pregunta no es solo dónde está el bloque, sino qué papel cumple dentro del movimiento.', mistake: 'Marcar un bloque sin identificar qué impulso o continuación representa.', question: '¿Qué aporta contexto a un Propulsion Block?', options: ['La estructura y el impulso relacionado', 'Un nombre atractivo', 'Una predicción fija del precio'], correct: 0, feedback: 'Bien: la función del bloque se evalúa dentro de la estructura y del movimiento que representa.' },
    20: { heading: 'Rejection Block: una zona de rechazo', intro: 'El Rejection Block se estudia alrededor de zonas donde el precio prueba un nivel y muestra rechazo. Las mechas y el cierre ayudan a describir la reacción, pero no son suficientes sin contexto.', points: [{ title: 'Extremo probado', text: 'Identificá el nivel donde el precio intentó avanzar y fue rechazado.' }, { title: 'Respuesta', text: 'Observá si la vela cierra lejos del extremo y si sigue un movimiento direccional.' }, { title: 'Estructura', text: 'Relacioná el rechazo con swings, liquidez y un posible cambio o continuación.' }], traderNote: 'Un rechazo es más útil cuando ocurre en una zona de interés previamente identificada.', mistake: 'Llamar Rejection Block a cualquier vela con mecha larga.', question: '¿Qué vuelve más relevante un rechazo?', options: ['Que aparezca en un nivel contextual y tenga respuesta posterior', 'Que tenga una mecha sin importar dónde', 'Que suceda lejos de cualquier estructura'], correct: 0, feedback: 'Correcto: el rechazo necesita nivel y contexto, además de observar qué hace el precio después.' },
    21: { heading: 'Reclaimed Order Block: una zona recuperada', intro: 'El Reclaimed Order Block se estudia como una zona de órdenes que el precio recupera después de haberla perdido o atravesado. La recuperación debe interpretarse en relación con estructura y cierres.', points: [{ title: 'Zona previa', text: 'Marcá el OB y entendé qué función tenía.' }, { title: 'Pérdida y recuperación', text: 'Observá si el precio atraviesa el nivel y luego vuelve a reclamarlo.' }, { title: 'Nueva reacción', text: 'Evaluá si el precio logra sostenerse en el lado recuperado.' }], traderNote: 'Diferenciá recuperar una zona de simplemente tocarla: la aceptación del precio es lo que importa.', mistake: 'Dar por recuperado un OB por una mecha que cruza el nivel y cierra de vuelta adentro.', question: '¿Qué es clave para analizar un Reclaimed OB?', options: ['La recuperación y aceptación de la zona', 'El color de una vela aislada', 'Que esté cerca de una media móvil'], correct: 0, feedback: 'Exacto: hay que observar si el precio recupera la zona y puede sostenerse allí.' },
    24: { heading: 'BPR: superposición de desequilibrios opuestos', intro: 'El Balanced Price Range se forma cuando una FVG alcista y una FVG bajista se superponen. El área representa un rango donde los desequilibrios se encuentran.', points: [{ title: 'Dos FVG opuestas', text: 'Identificá una zona de desequilibrio alcista y otra bajista.' }, { title: 'Área compartida', text: 'La superposición define el BPR que se estudia como punto de interés.' }, { title: 'Reacción', text: 'Observá si el precio respeta, atraviesa o reequilibra el área.' }], traderNote: 'Un BPR no predice solo la dirección: importa desde dónde llega el precio y qué liquidez tiene cerca.', mistake: 'Marcar un BPR sin que existan dos desequilibrios opuestos superpuestos.', question: '¿Qué define un BPR?', options: ['La superposición de FVG opuestas', 'Un único swing low', 'Un cruce de medias'], correct: 0, feedback: 'Correcto: el BPR es la región común entre desequilibrios opuestos.' },
    25: { heading: 'Volume Imbalance: una diferencia entre velas', intro: 'El Volume Imbalance se refiere a un desequilibrio observable entre cuerpos o zonas de velas adyacentes, según los criterios del modelo. No es lo mismo que volumen negociado alto.', points: [{ title: 'Compará velas', text: 'Revisá la relación entre cuerpos y niveles de apertura/cierre.' }, { title: 'No confundas términos', text: 'Volume Imbalance en esta metodología no significa necesariamente que el histograma de volumen sea alto.' }, { title: 'Contexto', text: 'La zona se estudia junto con estructura y otros desequilibrios.' }], traderNote: 'Separá el volumen de negociación del desequilibrio de precios: los nombres se parecen, pero no son idénticos.', mistake: 'Marcar Volume Imbalance solo porque una barra de volumen es grande.', question: '¿Una barra de volumen grande confirma por sí sola un Volume Imbalance SMC?', options: ['Sí, siempre', 'No; el concepto se refiere a una relación de precio específica', 'Solo si la vela es verde'], correct: 1, feedback: 'Exacto: no hay que confundir el histograma de volumen con la estructura de precios que describe el concepto.' },
    26: { heading: 'IOFED: una referencia dentro del desequilibrio', intro: 'El Institutional Order Flow Entry Drill se presenta como un punto de entrada relacionado con el inicio de una FVG y el flujo institucional. Requiere contexto de estructura y no debe aislarse.', points: [{ title: 'Primero el contexto', text: 'Definí el sesgo y la estructura antes de buscar una zona de entrada.' }, { title: 'Localizá el desequilibrio', text: 'Identificá la FVG y el punto de referencia que usa el modelo.' }, { title: 'Gestión', text: 'Definí invalidación, stop y riesgo antes de ejecutar.' }], traderNote: 'La técnica de entrada no reemplaza el motivo de la operación ni el plan de riesgo.', mistake: 'Usar el punto de entrada sin una hipótesis direccional o sin invalidación.', question: '¿Qué debería preceder a una entrada tipo IOFED?', options: ['Contexto y flujo de órdenes definidos', 'Una entrada al azar', 'Un objetivo sin stop'], correct: 0, feedback: 'Correcto: primero contexto, después zona de entrada y gestión del riesgo.' },
    27: { heading: 'Breakaway Gaps y RDRB', intro: 'El libro agrupa conceptos relacionados con brechas de ruptura y reequilibrio. Se estudia cómo el precio abandona una zona con decisión y cómo puede volver a entregar o equilibrar parte del movimiento.', points: [{ title: 'Ruptura', text: 'Observá si el precio se separa de una zona con movimiento claro.' }, { title: 'Reequilibrio', text: 'El precio puede volver a una parte del recorrido para reequilibrar.' }, { title: 'No anticipes', text: 'La vuelta a una brecha no implica que deba completarse ni que la tendencia vaya a continuar.' }], traderNote: 'Separá el evento inicial de ruptura del comportamiento posterior; cada fase aporta información distinta.', mistake: 'Suponer que toda brecha será rellenada por completo.', question: '¿Qué es importante al estudiar una brecha de ruptura?', options: ['Contexto de la ruptura y posible reequilibrio posterior', 'Asumir que siempre se rellena', 'Ignorar la dirección del impulso'], correct: 0, feedback: 'Bien: estudiá el impulso, la zona que dejó y la reacción posterior sin asumir un resultado fijo.' },
    29: { heading: 'Liquidez interna y externa del rango', intro: 'La IRL se encuentra dentro del rango, en zonas como FVG u OB; la ERL se ubica fuera de los extremos del rango, por ejemplo más allá de un máximo o mínimo relevante.', points: [{ title: 'IRL', text: 'Zonas internas que el precio puede visitar al moverse dentro del rango.' }, { title: 'ERL', text: 'Liquidez más allá de los extremos del rango.' }, { title: 'Movimiento entre zonas', text: 'El precio puede alternar entre reequilibrar zonas internas y buscar liquidez externa.' }], traderNote: 'Marcá primero el rango y después separá los objetivos internos de los que están fuera de sus extremos.', mistake: 'Llamar externa a la liquidez que está en el medio del rango.', question: '¿Dónde está la ERL?', options: ['Fuera de los extremos del rango', 'Siempre en el punto medio', 'Dentro de cada vela'], correct: 0, feedback: 'Correcto: la liquidez externa se sitúa más allá de los extremos del rango.' },
    30: { heading: 'HRLR y LRLR describen la resistencia del recorrido', intro: 'El libro distingue movimientos hacia liquidez con alta resistencia (HRLR) y baja resistencia (LRLR). El concepto ayuda a pensar si el camino hacia un objetivo está lleno de obstáculos o relativamente despejado.', points: [{ title: 'HRLR', text: 'El precio encuentra zonas intermedias, desequilibrios o bloques que pueden frenar el recorrido.' }, { title: 'LRLR', text: 'El camino hacia el objetivo tiene pocos obstáculos y el movimiento puede ser más directo.' }, { title: 'Objetivos y entradas', text: 'La lectura puede ayudar a proyectar objetivos o localizar zonas de reacción.' }], traderNote: 'Antes de proyectar un objetivo, revisá qué zonas relevantes hay entre el precio actual y la liquidez buscada.', mistake: 'Suponer que un LRLR garantiza un movimiento rápido o que un HRLR impedirá alcanzar el objetivo.', question: '¿Qué describe un LRLR?', options: ['Un camino con pocos obstáculos hacia la liquidez', 'Un patrón que siempre revierte', 'Una orden de mercado'], correct: 0, feedback: 'Exacto: LRLR describe un recorrido relativamente libre hacia un objetivo de liquidez.' },
    31: { heading: 'Liquidity Void: un tramo recorrido con rapidez', intro: 'Un Liquidity Void es un área donde el precio se movió rápidamente y dejó un tramo poco equilibrado. Puede atraer un retorno, pero no existe obligación de rellenarlo.', points: [{ title: 'Movimiento acelerado', text: 'Buscá un tramo direccional con poca negociación relativa en el camino.' }, { title: 'Zona de interés', text: 'El vacío puede servir como referencia si el precio vuelve.' }, { title: 'Contexto', text: 'Relacioná el void con FVG, estructura y el objetivo de liquidez.' }], traderNote: 'Un vacío describe cómo se movió el precio; no es una predicción automática de que volverá.', mistake: 'Esperar siempre que el precio rellene todo el tramo.', question: '¿Qué representa un Liquidity Void?', options: ['Un tramo de movimiento rápido y poco equilibrado', 'Un soporte infalible', 'Un dato fundamental de la empresa'], correct: 0, feedback: 'Bien: es una zona de movimiento rápido; su posible relleno debe evaluarse en contexto.' },
    32: { heading: 'Inducement: cuidado con el movimiento que atrae entradas', intro: 'El Inducement se estudia como un nivel o movimiento que puede atraer a los traders hacia un lado antes de que el precio busque otra zona de liquidez. Se analiza en relación con la estructura principal.', points: [{ title: 'Nivel atractivo', text: 'Puede parecer un punto obvio de entrada o ruptura.' }, { title: 'Liquidez acumulada', text: 'Las órdenes alrededor del nivel pueden convertirse en objetivo de un barrido.' }, { title: 'Confirmación', text: 'No asumas manipulación solo porque una operación sale mal; buscá evidencia en el gráfico.' }], traderNote: 'Preguntate qué liquidez puede haber por encima o debajo del nivel obvio y qué estructura lo respalda.', mistake: 'Usar la palabra inducement para explicar retrospectivamente cualquier movimiento engañoso.', question: '¿Cómo conviene interpretar un posible inducement?', options: ['Como hipótesis de atracción de liquidez que requiere contexto', 'Como prueba de manipulación en cada gráfico', 'Como señal automática de compra'], correct: 0, feedback: 'Correcto: se estudia como una hipótesis contextual, no como una explicación automática.' },
    35: { heading: 'La desviación estándar proyecta extensiones, no certezas', intro: 'El capítulo estudia el uso de desviaciones estándar para medir extensiones respecto de un rango o referencia. Estas proyecciones ayudan a organizar escenarios, pero no fijan el máximo o mínimo futuro.', points: [{ title: 'Definí la referencia', text: 'El cálculo necesita un rango o movimiento de partida coherente.' }, { title: 'Proyección', text: 'Los niveles pueden señalar zonas de extensión o reacción potencial.' }, { title: 'Confluencia', text: 'Combiná las proyecciones con estructura y liquidez, no las uses solas.' }], traderNote: 'Un nivel estadístico es una referencia para observar, no una barrera que el precio deba respetar.', mistake: 'Tratar una extensión estadística como objetivo garantizado.', question: '¿Cómo se deben usar las desviaciones estándar?', options: ['Como referencias de escenario junto con contexto', 'Como garantía de reversión', 'Como sustituto de la estructura'], correct: 0, feedback: 'Exacto: sirven como referencias, no como pronósticos infalibles.' },
    36: { heading: 'Three Drives: tres impulsos y posible agotamiento', intro: 'El patrón Three Drives estudia tres impulsos sucesivos hacia un extremo. El tercer impulso puede señalar agotamiento de liquidez, especialmente si el precio llega a una zona relevante y aparece una reacción.', points: [{ title: 'Tres recorridos', text: 'Identificá impulsos comparables hacia la misma dirección.' }, { title: 'Zona de interés', text: 'Buscá coincidencia con liquidez o un POI significativo.' }, { title: 'Reacción', text: 'Esperá señal de agotamiento o cambio estructural antes de asumir reversión.' }], traderNote: 'Tres impulsos por sí solos no son una entrada; el nivel y la reacción posterior son fundamentales.', mistake: 'Vender automáticamente el tercer impulso sin confirmación.', question: '¿Qué refuerza la lectura de Three Drives?', options: ['Llegada a una zona de interés y reacción posterior', 'Solo contar tres velas', 'Ignorar liquidez y estructura'], correct: 0, feedback: 'Correcto: el patrón gana contexto con un POI y evidencia de reacción.' },
    37: { heading: 'Candle Range Theory: leé el rango de la vela', intro: 'La Candle Range Theory estudia el rango entre máximo y mínimo de una vela y la relación entre cuerpo y mechas para plantear escenarios de expansión, equilibrio o manipulación.', points: [{ title: 'Range', text: 'La distancia entre máximo y mínimo indica amplitud del intervalo.' }, { title: 'Cuerpo y mechas', text: 'El cuerpo muestra apertura-cierre; las mechas muestran extremos visitados y rechazados.' }, { title: 'Contexto', text: 'Combiná la vela con FVG, displacement y liquidez para evitar leerla aislada.' }], traderNote: 'Primero anotá máximo, mínimo y cierre; después compará cómo responde el precio respecto de esos extremos.', mistake: 'Interpretar el rango de una vela sin considerar el marco temporal ni la estructura anterior.', question: '¿Qué mide el range de una vela?', options: ['La distancia entre máximo y mínimo', 'Solo el cuerpo', 'El volumen de la sesión completa'], correct: 0, feedback: 'Bien: el rango de vela es la amplitud entre su máximo y mínimo.' },
    38: { heading: 'Seek and Destroy: reconocer sesiones de ida y vuelta', intro: 'El modelo Seek and Destroy describe un contexto intradía en el que el precio puede barrer niveles y oscilar sin desarrollar una expansión direccional limpia. Requiere cautela y lectura de tiempo/liquidez.', points: [{ title: 'Contexto de sesión', text: 'Observá si el precio realiza barridos y vuelve al rango en vez de sostener una dirección.' }, { title: 'Falsas rupturas', text: 'No asumas que toda ruptura intradía va a continuar.' }, { title: 'Disciplina', text: 'Si el escenario no ofrece claridad, no operar también es una decisión válida.' }], traderNote: 'El objetivo es reconocer cuándo el mercado no está entregando un movimiento limpio, no forzar una entrada.', mistake: 'Operar cada ruptura durante una sesión errática.', question: '¿Qué respuesta puede ser adecuada si la sesión no muestra una dirección clara?', options: ['Forzar una operación', 'Esperar claridad o no operar', 'Aumentar el riesgo para compensar'], correct: 1, feedback: 'Correcto: esperar es preferible a forzar entradas en un entorno sin claridad.' },
    39: { heading: 'SMT Divergence: comparar activos relacionados', intro: 'La divergencia SMT compara el comportamiento de dos activos relacionados. Si uno supera un extremo previo y el otro no lo acompaña, puede aparecer una divergencia que aporta contexto adicional.', points: [{ title: 'Elegí pares relacionados', text: 'La comparación debe tener sentido por correlación o relación de mercado.' }, { title: 'Compará extremos equivalentes', text: 'Revisá si ambos activos confirman o divergen en máximos/mínimos relevantes.' }, { title: 'No es señal aislada', text: 'La divergencia se combina con estructura, liquidez y reacción.' }], traderNote: 'La pregunta útil es qué activo confirmó el extremo y cuál no; después mirá dónde ocurre dentro de la estructura.', mistake: 'Comparar activos sin relación y llamar SMT a cualquier diferencia.', question: '¿Qué requiere una lectura SMT razonable?', options: ['Dos activos relacionados y extremos comparables', 'Dos activos elegidos al azar', 'Un indicador RSI aislado'], correct: 0, feedback: 'Exacto: compará activos relacionados y niveles equivalentes.' },
    40: { heading: 'IPDA: un marco conceptual de entrega del precio', intro: 'El libro presenta el Interbank Price Delivery Algorithm como un marco para interpretar cómo el precio se mueve entre zonas de liquidez y reequilibra desequilibrios. No debe tratarse como un algoritmo verificable que revele cada movimiento futuro.', points: [{ title: 'Zonas', text: 'Identificá liquidez interna/externa y desequilibrios relevantes.' }, { title: 'Secuencia', text: 'Observá si el precio alterna entre buscar liquidez y reequilibrar.' }, { title: 'Hipótesis', text: 'Usá el modelo para organizar escenarios, no para afirmar intención institucional con certeza.' }], traderNote: 'Describí lo observable: nivel barrido, zona reequilibrada y siguiente objetivo probable.', mistake: 'Presentar el IPDA como explicación segura de cualquier movimiento de precio.', question: '¿Cómo conviene usar el IPDA?', options: ['Como marco de lectura de escenarios y liquidez', 'Como predicción infalible', 'Como sustituto del riesgo'], correct: 0, feedback: 'Bien: es un marco conceptual, no una garantía de dirección.' },
    41: { heading: 'Killzones: el tiempo también es contexto', intro: 'Las Killzones son ventanas horarias que el enfoque ICT observa por la actividad y volatilidad que suelen concentrarse en ciertos momentos de las sesiones. Los horarios dependen de zona horaria y cambios estacionales.', points: [{ title: 'Preparación', text: 'Marcá niveles de liquidez y POIs antes de la ventana temporal.' }, { title: 'Observación', text: 'Buscá la reacción en niveles relevantes cuando comienza la sesión.' }, { title: 'Horario local', text: 'Convertí correctamente la hora según mercado, zona horaria y horario de verano.' }], traderNote: 'La ventana horaria aporta contexto, pero no obliga a operar ni reemplaza la estructura.', mistake: 'Creer que una Killzone garantiza un movimiento o usar un horario mal convertido.', question: '¿Qué aporta una Killzone al análisis?', options: ['Contexto temporal para observar actividad y reacción', 'Garantía de volatilidad rentable', 'Una señal automática de compra'], correct: 0, feedback: 'Correcto: es contexto temporal, no una señal garantizada.' },
    42: { heading: 'Macro Times: ventanas cortas de actividad', intro: 'Los Macro Times son intervalos más acotados dentro de la sesión que el libro utiliza para observar movimientos rápidos, barridos y desplazamientos.', points: [{ title: 'Antes del intervalo', text: 'Marcá los niveles de liquidez y FVG que podrían importar.' }, { title: 'Durante el intervalo', text: 'Observá si hay barrido, displacement o cambio estructural.' }, { title: 'Después', text: 'Evaluá el resultado y evitá atribuir significado a cada movimiento pequeño.' }], traderNote: 'El tiempo puede afinar la observación; la señal necesita precio, nivel y confirmación.', mistake: 'Entrar solo porque empezó un horario etiquetado como macro.', question: '¿Qué debe acompañar el horario para que sea útil?', options: ['Niveles de precio y confirmación', 'Una entrada automática', 'La ausencia de un plan'], correct: 0, feedback: 'Exacto: el horario se combina con niveles, estructura y confirmación.' },
    44: { heading: 'Perfil de la semana: organizar escenarios por día', intro: 'El perfil semanal estudia cómo puede desarrollarse el rango y la dirección a lo largo de los días de la semana. Es una guía de contexto, no un patrón que siempre se repite.', points: [{ title: 'Rango de referencia', text: 'Observá aperturas, máximos y mínimos previos de la semana.' }, { title: 'Desarrollo', text: 'Compará el comportamiento real con escenarios semanales posibles.' }, { title: 'Adaptación', text: 'Actualizá el sesgo cuando la estructura contradiga el escenario inicial.' }], traderNote: 'Usá el perfil como hipótesis inicial y dejá que el precio confirme o invalide el plan.', mistake: 'Forzar el comportamiento del precio para que coincida con un perfil semanal esperado.', question: '¿Qué es un perfil semanal bien usado?', options: ['Una hipótesis adaptable al precio', 'Un calendario que garantiza la dirección', 'Un reemplazo del análisis diario'], correct: 0, feedback: 'Correcto: el perfil organiza escenarios, pero el precio real manda.' },
    45: { heading: 'Medianoche y 8:30: referencias de tiempo y precio', intro: 'El libro estudia estos horarios como referencias utilizadas en ciertos modelos ICT para organizar rangos, aperturas y posibles movimientos. Hay que respetar la zona horaria y el horario estacional.', points: [{ title: 'Marcar referencia', text: 'Identificá el precio correspondiente a la hora definida por el modelo.' }, { title: 'Construir contexto', text: 'Compará el precio con los niveles de liquidez y el rango de sesión.' }, { title: 'No universalizar', text: 'Verificá la convención horaria del mercado que estás analizando.' }], traderNote: 'Una línea horaria solo aporta contexto si está correctamente convertida y combinada con estructura.', mistake: 'Usar la hora de Nueva York como si fuera siempre la misma hora argentina.', question: '¿Qué es esencial al aplicar estas referencias horarias?', options: ['Confirmar zona horaria y horario de verano', 'Ignorar el horario del activo', 'Usar el precio de cualquier vela'], correct: 0, feedback: 'Exacto: la conversión horaria correcta es esencial.' },
    46: { heading: 'CBDR: un rango temporal de referencia', intro: 'El Central Bank Dealers Range utiliza un rango definido por el modelo en un horario concreto para estudiar posibles expansiones posteriores. Sus horas deben verificarse según la convención del libro y la zona horaria.', points: [{ title: 'Construí el rango', text: 'Marcá máximo y mínimo durante el intervalo definido.' }, { title: 'Medí la amplitud', text: 'El rango sirve como referencia para escenarios de expansión.' }, { title: 'Contextualizá', text: 'Combiná la lectura con liquidez, estructura y calendario.' }], traderNote: 'Primero respetá la ventana horaria del modelo; después evaluá la expansión, sin asumir que ocurrirá.', mistake: 'Dibujar el CBDR con horas incorrectas o tratar sus proyecciones como certeza.', question: '¿Qué define el rango CBDR?', options: ['Un intervalo horario específico del modelo', 'Cualquier rango elegido al azar', 'Un patrón de tres velas'], correct: 0, feedback: 'Correcto: el CBDR se define por una ventana horaria concreta.' },
    47: { heading: 'NWOG y NDOG: brechas de apertura', intro: 'NWOG y NDOG son brechas de apertura semanal y diaria. El libro las trata como referencias de precio que pueden servir para observar desequilibrios y zonas de reacción.', points: [{ title: 'NDOG', text: 'New Day Opening Gap: brecha asociada a la apertura diaria.' }, { title: 'NWOG', text: 'New Week Opening Gap: brecha asociada a la apertura semanal.' }, { title: 'Uso', text: 'Marcá los límites y observá cómo interactúa el precio; no asumas que siempre será rellenada.' }], traderNote: 'Registrá el gap y su marco temporal exacto. La reacción posterior es más importante que la etiqueta.', mistake: 'Suponer que toda brecha de apertura tiene que cerrarse.', question: '¿Qué diferencia a NWOG de NDOG?', options: ['NWOG es semanal y NDOG diaria', 'NWOG es un Order Block', 'NDOG es un tipo de stop loss'], correct: 0, feedback: 'Bien: NWOG corresponde a la apertura semanal y NDOG a la diaria.' },
    48: { heading: 'El calendario económico forma parte del contexto', intro: 'Las publicaciones macroeconómicas y los resultados pueden elevar la volatilidad y alterar niveles técnicos. El libro incluye el calendario como parte de la preparación temporal.', points: [{ title: 'Revisá eventos', text: 'Identificá publicaciones relevantes para el activo y el mercado.' }, { title: 'Ajustá expectativas', text: 'Durante eventos importantes puede haber spreads, gaps y movimientos abruptos.' }, { title: 'Protegé el riesgo', text: 'Considerá si tu plan contempla operar antes, durante o después del evento.' }], traderNote: 'Un gráfico bien leído no elimina el riesgo de un evento. La decisión de operar también depende del calendario.', mistake: 'Ignorar noticias programadas y atribuir todo movimiento a estructura SMC.', question: '¿Por qué revisar el calendario económico?', options: ['Porque puede cambiar volatilidad y ejecución', 'Porque predice con certeza la vela siguiente', 'Porque reemplaza la estructura'], correct: 0, feedback: 'Correcto: los eventos pueden alterar volatilidad y calidad de ejecución.' },
    49: { heading: 'Power of 3: acumulación, manipulación y distribución', intro: 'El modelo PO3 organiza un posible ciclo en tres fases: acumulación de rango, manipulación o movimiento engañoso y distribución direccional. Es un modelo de lectura, no una secuencia obligatoria.', points: [{ title: 'Acumulación', text: 'El precio se mueve dentro de un rango y puede concentrar liquidez.' }, { title: 'Manipulación', text: 'Puede barrer un extremo del rango antes de moverse en la dirección contraria.' }, { title: 'Distribución', text: 'Se desarrolla el movimiento direccional que el modelo intenta identificar.' }], traderNote: 'No decidas que hubo manipulación solo mirando el resultado final: identificá rango, barrido y desplazamiento en orden.', mistake: 'Forzar las tres fases en cualquier sesión lateral.', question: '¿Cuáles son las fases de PO3?', options: ['Acumulación, manipulación y distribución', 'Compra, venta y dividendo', 'BOS, FVG y EMA'], correct: 0, feedback: 'Exacto: esas son las tres fases que organiza el modelo.' },
    50: { heading: 'Judas Swing: un movimiento inicial que engaña', intro: 'El Judas Swing describe un movimiento inicial que puede ir en una dirección, barrer liquidez y luego girar hacia el movimiento principal esperado en el modelo. El tiempo y el contexto son centrales.', points: [{ title: 'Contexto previo', text: 'Marcá los niveles de liquidez y el sesgo antes de la sesión.' }, { title: 'Movimiento inicial', text: 'Observá si el precio realiza un barrido contrario al escenario esperado.' }, { title: 'Confirmación', text: 'Buscá desplazamiento y cambio estructural antes de inferir el giro.' }], traderNote: 'No llames Judas Swing a cualquier retroceso. Necesitás contexto horario, liquidez y una reacción posterior.', mistake: 'Operar contra el primer movimiento sin esperar evidencia del giro.', question: '¿Qué ayuda a validar un posible Judas Swing?', options: ['Contexto temporal, barrido y reacción confirmatoria', 'Solo una vela larga', 'Una entrada inmediata sin stop'], correct: 0, feedback: 'Bien: el patrón necesita contexto y evidencia de que el movimiento inicial fue revertido.' },
    52: { heading: 'OTE: una zona de retroceso, no una garantía', intro: 'Optimal Trade Entry utiliza niveles de retroceso de Fibonacci dentro de un movimiento definido para buscar una zona de entrada potencial. El sesgo y la estructura deben establecerse primero.', points: [{ title: 'Elegí el impulso', text: 'Medí desde el origen hasta el extremo del movimiento relevante.' }, { title: 'Esperá el retroceso', text: 'Usá la zona OTE como área de interés, no como señal automática.' }, { title: 'Confirmá', text: 'Combiná el nivel con estructura, liquidez y reacción del precio.' }], traderNote: 'Primero la idea y la estructura; después Fibonacci para precisar una posible zona.', mistake: 'Comprar o vender solo porque el precio llegó a un nivel Fibonacci.', question: '¿Qué condición mejora el uso del OTE?', options: ['Un sesgo y un impulso estructural claros', 'Usar Fibonacci en cualquier tramo', 'Ignorar el stop loss'], correct: 0, feedback: 'Correcto: el OTE debe aplicarse sobre un movimiento relevante y dentro de un contexto claro.' },
    53: { heading: 'Turtle Soup: falsa ruptura y recuperación', intro: 'Turtle Soup busca una posible reversión después de que el precio rompe un máximo o mínimo relevante y vuelve a recuperar el nivel. La idea se relaciona con un barrido de liquidez y fallo de continuación.', points: [{ title: 'Nivel previo', text: 'Marcá un máximo o mínimo que otros participantes puedan observar.' }, { title: 'Falsa ruptura', text: 'El precio supera el nivel pero no logra sostenerse fuera de él.' }, { title: 'Recuperación', text: 'Esperá que el precio vuelva al rango y confirme la reacción antes de evaluar una operación.' }], traderNote: 'Una ruptura que falla puede ser informativa; no todas las rupturas fallidas producen un giro grande.', mistake: 'Entrar contra el nivel antes de que el precio muestre que no puede sostener la ruptura.', question: '¿Qué busca el modelo Turtle Soup?', options: ['Una falsa ruptura y recuperación del nivel', 'Una tendencia que nunca retrocede', 'Una FVG sin estructura'], correct: 0, feedback: 'Exacto: la lógica es detectar la ruptura fallida y la recuperación del nivel.' },
    51: { heading: 'Market Maker Buy/Sell Model: estructura y liquidez en fases', intro: 'Los modelos de compra y venta del Market Maker organizan una secuencia de consolidación, generación de liquidez, reversión desde una zona de interés y búsqueda de liquidez al otro lado.', points: [{ title: 'Contexto superior', text: 'Definí la estructura y el sesgo en la temporalidad mayor.' }, { title: 'Programa contrario', text: 'Observá el movimiento del marco menor hacia una PD Array relevante.' }, { title: 'Confirmación y entrada', text: 'Buscá MSS o divergencia y luego un retroceso a una FVG según el modelo.' }], traderNote: 'La secuencia es contextual: no todas las consolidaciones se convierten en un modelo de Market Maker.', mistake: 'Reconocer el modelo solo después de que el movimiento ya terminó.', question: '¿Qué se busca antes de ejecutar el modelo?', options: ['Contexto HTF, zona de interés y confirmación LTF', 'Solo una consolidación', 'Una entrada sin invalidación'], correct: 0, feedback: 'Correcto: el modelo combina contexto superior, zona de interés y confirmación en temporalidad menor.' },
    54: { heading: 'ICT 2022: un modelo de confluencias', intro: 'El modelo ICT 2022 combina sesgo, búsqueda de liquidez, cambio estructural en temporalidad menor y retorno a un FVG. Es una secuencia de condiciones, no un patrón que deba aparecer todos los días.', points: [{ title: 'Sesgo y liquidez', text: 'Establecé un objetivo probable y esperá que el precio alcance una zona de interés.' }, { title: 'MSS / displacement', text: 'Buscá una ruptura estructural clara en el marco temporal de ejecución.' }, { title: 'Retesteo', text: 'El retorno a la FVG puede ofrecer una zona de entrada según el plan.' }], traderNote: 'Si falta una condición clave, no fuerces el modelo. Esperar también es parte del sistema.', mistake: 'Entrar por una FVG sin que antes exista contexto y cambio estructural.', question: '¿Qué secuencia se ajusta mejor al modelo?', options: ['Sesgo, liquidez, MSS y retroceso a FVG', 'Cualquier FVG y entrada inmediata', 'Cruce de medias y objetivo arbitrario'], correct: 0, feedback: 'Bien: el modelo integra contexto, liquidez, cambio estructural y retroceso.' },
    55: { heading: 'Unicorn Model: confluencia de Breaker y FVG', intro: 'El libro describe el Unicorn como un modelo que busca la superposición de un Breaker Block y una FVG, después de una secuencia estructural y captura de liquidez.', points: [{ title: 'Estructura y liquidez', text: 'Identificá la secuencia de swing y la ruptura que define el escenario.' }, { title: 'Superposición', text: 'Buscá que el Breaker y la FVG compartan una zona.' }, { title: 'Retesteo', text: 'Esperá que el precio vuelva al área compartida y muestre una reacción.' }], traderNote: 'La zona de superposición es el punto de interés del modelo, pero necesitás confirmación y riesgo definido.', mistake: 'Llamar Unicorn a cualquier FVG cerca de un bloque sin que exista la confluencia exigida.', question: '¿Qué confluencia define el área Unicorn?', options: ['Breaker Block superpuesto con FVG', 'Dos medias móviles', 'Un máximo y un RSI'], correct: 0, feedback: 'Correcto: la superposición de Breaker Block y FVG es la confluencia central del modelo.' },
    56: { heading: 'Silver Bullet: tiempo, liquidez y FVG', intro: 'Silver Bullet es un modelo de tiempo específico que combina ventanas horarias, búsqueda de liquidez y Fair Value Gaps. El horario es parte de las condiciones, no un disparador aislado.', points: [{ title: 'Ventana temporal', text: 'Verificá el horario de referencia y la zona horaria correcta.' }, { title: 'Liquidez y desplazamiento', text: 'Observá un barrido o movimiento hacia un nivel significativo y una respuesta direccional.' }, { title: 'FVG y entrada', text: 'Buscá el desequilibrio y el retroceso que encaja con las reglas del modelo.' }], traderNote: 'Sin horario correcto, contexto y confirmación, una FVG cualquiera no es Silver Bullet.', mistake: 'Operar cada FVG durante el día y etiquetarla como Silver Bullet.', question: '¿Qué combina el modelo Silver Bullet?', options: ['Ventana temporal, liquidez y FVG', 'Solo una vela verde', 'Un Order Block sin contexto'], correct: 0, feedback: 'Exacto: el modelo integra tiempo, liquidez y desequilibrio.' },
  }
  if (content[id]) return content[id]
  const chapter = lessonCatalog.find(c => c.id === id) || lessonCatalog[0]
  const title = chapter.title
  return {
    heading: `Entendé ${title} dentro del contexto SMC`,
    intro: `${title} es parte del recorrido del libro. La clave no es memorizar la etiqueta aislada, sino entender qué describe, en qué contexto aparece y qué evidencia invalida la hipótesis. Esta lección es una introducción resumida; contrastá los detalles con el capítulo original del PDF.`,
    points: [
      { title: 'Definición', text: `${chapter.subtitle || title}. Identificá qué elemento del precio describe el concepto.` },
      { title: 'Contexto', text: 'Relacioná la señal con la estructura, la temporalidad superior y las zonas de liquidez relevantes.' },
      { title: 'Confirmación', text: 'Buscá evidencia observable, definí invalidación y evitá convertir una hipótesis en certeza.' },
    ],
    traderNote: 'Preguntate qué observación del gráfico respalda la etiqueta y qué tendría que pasar para descartarla.',
    mistake: 'Aplicar el nombre del patrón sin comprobar sus condiciones, su contexto ni su invalidación.',
    question: `¿Cuál es la forma más sólida de estudiar ${title}?`,
    options: ['Memorizar el nombre y operar cada aparición', 'Evaluar definición, contexto, confirmación e invalidación', 'Ignorar la estructura y mirar solo una vela'],
    correct: 1,
    feedback: 'Correcto: los conceptos SMC se interpretan en conjunto. Volvé al capítulo original para estudiar los criterios específicos de este modelo.',
  }
}

const visualForChapter = id => {
  const map = {
    9: { title: 'Ruptura a favor de la estructura', alt: 'Esquema de ruptura BOS' },
    10: { title: 'Ruptura contra la estructura previa', alt: 'Esquema de ruptura CHOCH' },
    11: { title: 'Ruptura y desplazamiento', alt: 'Esquema de MSS' },
    15: { title: 'Zona de origen del impulso', alt: 'Esquema de Order Block' },
    17: { title: 'El bloque falla y cambia de función', alt: 'Esquema de Breaker Block' },
    22: { title: 'Ineficiencia entre tres velas', alt: 'Esquema de Fair Value Gap' },
    23: { title: 'La brecha cambia de función', alt: 'Esquema de Inverse Fair Value Gap' },
    33: { title: 'El precio barre un nivel de liquidez', alt: 'Esquema de Liquidity Sweep' },
  }
  return map[id] || { title: 'Leé el precio dentro de su contexto', alt: 'Esquema didáctico de velas' }
}

const glossary = [
  { term: 'BOS', name: 'Break of Structure', family: 'Estructura', definition: 'Ruptura de un máximo o mínimo estructural a favor de la tendencia predominante.', caution: 'Puede ser alcista o bajista; depende de la dirección del flujo.' },
  { term: 'CHOCH', name: 'Change of Character', family: 'Estructura', definition: 'Ruptura de estructura en contra de la tendencia anterior, que señala una posible reversión.', caution: 'No garantiza que la nueva tendencia esté confirmada.' },
  { term: 'MSS', name: 'Market Structure Shift', family: 'Estructura', definition: 'Cambio estructural inicial, en el libro asociado a ruptura de swing contra la tendencia y displacement.', caution: 'El uso exacto puede variar entre escuelas SMC.' },
  { term: 'CISD', name: 'Change in the State of Delivery', family: 'Estructura', definition: 'Cambio en la dirección de la entrega del precio, de flujo comprador a vendedor o viceversa.' },
  { term: 'HH', name: 'Higher High', family: 'Estructura', definition: 'Máximo más alto que el máximo estructural anterior.' },
  { term: 'HL', name: 'Higher Low', family: 'Estructura', definition: 'Mínimo más alto que el mínimo estructural anterior.' },
  { term: 'LH', name: 'Lower High', family: 'Estructura', definition: 'Máximo más bajo que el máximo estructural anterior.' },
  { term: 'LL', name: 'Lower Low', family: 'Estructura', definition: 'Mínimo más bajo que el mínimo estructural anterior.' },
  { term: 'OB', name: 'Order Block', family: 'Bloques', definition: 'Zona asociada al origen de un movimiento relevante; requiere contexto y validación.' },
  { term: 'BB', name: 'Breaker Block', family: 'Bloques', definition: 'Order Block fallido que invierte su función entre soporte y resistencia.', caution: 'La ruptura y la nueva función son claves.' },
  { term: 'MB', name: 'Mitigation Block', family: 'Bloques', definition: 'Bloque de mitigación; se estudia como zona relacionada con el ajuste o mitigación de posiciones.' },
  { term: 'FVG', name: 'Fair Value Gap', family: 'Ineficiencias', definition: 'Desequilibrio que se identifica comparando los extremos de la primera y tercera vela de una secuencia de tres.' },
  { term: 'IFVG', name: 'Inverse Fair Value Gap', family: 'Ineficiencias', definition: 'FVG que se atraviesa y puede cambiar de función, de soporte a resistencia o al revés.' },
  { term: 'BPR', name: 'Balanced Price Range', family: 'Ineficiencias', definition: 'Área de superposición entre desequilibrios opuestos.' },
  { term: 'CE', name: 'Consequent Encroachment', family: 'Ineficiencias', definition: 'Punto medio (50 %) de un desequilibrio como una FVG.' },
  { term: 'MT', name: 'Mean Threshold', family: 'Bloques', definition: 'Punto medio de un Order Block u otra estructura.' },
  { term: 'BSL', name: 'Buy-Side Liquidity', family: 'Liquidez', definition: 'Liquidez que puede concentrarse por encima de máximos relevantes.' },
  { term: 'SSL', name: 'Sell-Side Liquidity', family: 'Liquidez', definition: 'Liquidez que puede concentrarse por debajo de mínimos relevantes.' },
  { term: 'Sweep', name: 'Liquidity Sweep', family: 'Liquidez', definition: 'Barrido de un nivel de liquidez; la reacción posterior ayuda a distinguirlo de una ruptura sostenida.' },
  { term: 'IRL', name: 'Internal Range Liquidity', family: 'Liquidez', definition: 'Liquidez interna al rango, asociada a elementos como FVG y OB.' },
  { term: 'ERL', name: 'External Range Liquidity', family: 'Liquidez', definition: 'Liquidez externa del rango, por ejemplo más allá de sus máximos o mínimos.' },
  { term: 'POI', name: 'Point of Interest', family: 'Contexto', definition: 'Zona o nivel de interés que merece observarse por su confluencia con el análisis.' },
  { term: 'HTF', name: 'Higher Time Frame', family: 'Contexto', definition: 'Temporalidad superior, útil para situar el contexto del movimiento.' },
  { term: 'LTF', name: 'Lower Time Frame', family: 'Contexto', definition: 'Temporalidad inferior, que puede ayudar a estudiar el detalle de una entrada.' },
  { term: 'DOL', name: 'Draw on Liquidity', family: 'Liquidez', definition: 'Posible objetivo de precio en una zona donde se concentra liquidez.' },
  { term: 'OTE', name: 'Optimal Trade Entry', family: 'Estrategias', definition: 'Modelo de entrada óptima basado en retrocesos y niveles de Fibonacci según el enfoque ICT.' },
  { term: 'PO3', name: 'Power of 3', family: 'Estrategias', definition: 'Modelo que organiza el movimiento en acumulación, manipulación y distribución.' },
  { term: 'SMT', name: 'SMT Divergence', family: 'Avanzado', definition: 'Divergencia entre activos relacionados que puede aportar contexto adicional.' },
  { term: 'Killzone', name: 'Ventana temporal', family: 'Tiempo', definition: 'Periodo horario en el que el modelo ICT presta especial atención a la actividad del mercado.' },
  { term: 'Displacement', name: 'Desplazamiento', family: 'Estructura', definition: 'Movimiento direccional claro que puede respaldar una ruptura estructural.' },
]

const checklist = {
  structure: ['Identifiqué la tendencia o el rango en la temporalidad superior.', 'Marqué swings relevantes, no cada zigzag menor.', 'Separé BOS, CHOCH y MSS según contexto y tipo de ruptura.'],
  zones: ['Marqué posibles BSL/SSL y niveles de liquidez cercanos.', 'Validé el origen y los límites de la FVG u OB.', 'Comprobé si existe confluencia con otro POI.'],
  confirmation: ['Esperé ruptura con cierre/desplazamiento cuando corresponde.', 'Observé la reacción o retesteo en la zona.', 'Definí qué invalidaría mi hipótesis.'],
  risk: ['Calculé el riesgo antes de entrar.', 'Definí stop y tamaño de posición de acuerdo con mi plan.', 'No estoy entrando solo por miedo a perderme el movimiento.'],
}
const allChecklistItems = computed(() => Object.values(checklist).flat())

function selectLesson(id) {
  selectedChapter.value = id
  activeTab.value = 'curso'
  quizAnswer.value = null
  quizSubmitted.value = false
  // Mantener la posición de lectura al cambiar de lección.
  // No hacer scroll global: el usuario debe conservar el foco en la ruta de aprendizaje.
}
function chooseAnswer(i) { quizAnswer.value = i; quizSubmitted.value = true }
function resetQuiz() { quizAnswer.value = null; quizSubmitted.value = false }
function toggleCompleted(id) {
  completed.value = completed.value.includes(id) ? completed.value.filter(n => n !== id) : [...completed.value, id]
  if (typeof localStorage !== 'undefined') localStorage.setItem('smc-academy-completed-v1', JSON.stringify(completed.value))
}
function nextLesson() { if (selectedChapter.value < Math.max(...lessonCatalog.map(c => c.id))) selectLesson(selectedChapter.value + 1); else selectLesson(1) }
function previousLesson() { if (selectedChapter.value > 1) selectLesson(selectedChapter.value - 1) }
function replayAnimation() { animationKey.value += 1 }
function scrollTop() { if (typeof window !== 'undefined') window.scrollTo({ top: 0, behavior: 'smooth' }) }

if (typeof localStorage !== 'undefined') {
  try {
    const saved = JSON.parse(localStorage.getItem('smc-academy-completed-v1') || '[]')
    if (Array.isArray(saved)) completed.value = saved.filter(id => lessonCatalog.some(c => c.id === id))
  } catch { completed.value = [] }
}
watch(selectedChapter, () => { resetQuiz() })
</script>

